有以下程序，该程序的输出结果为（　）
#include <stdio.h>
#include <string.h>
int main()
{
    char s[10]="121";
    int k=0,a=0,b=0;
    do
    {
        k++;
        if(k%2==0)
        {
            a=a+s[k]-'0';
            continue;
        }
        b=b+(s[k]-'0');
        a=a+s[k]-'0';
    }while(s[k+1]);
    printf("k=%d a=%d b=%d\n",k,a,b);
    return 0;
}

